import{_ as a,o as t,c as r,ag as i}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Vector Family proposals","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/vector/index.md","filePath":"proposals/vector/index.md"}'),o={name:"proposals/vector/index.md"};function s(n,e,d,c,h,l){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="vector-family-proposals" tabindex="-1">Vector Family proposals <a class="header-anchor" href="#vector-family-proposals" aria-label="Permalink to &quot;Vector Family proposals&quot;">​</a></h1><p>The Vector Family, <code>vector.forms.takoform.com</code>, fixes the fixed-dimension dense vector index shape — namespaced records queried by top-k similarity — selected by <a href="./../../spec/decisions/0043-forms-target-popular-vendor-locked-primitives.html">decision 0043</a>. Its member preserves, completely, the application-visible semantics of that proven shape without naming its vendor (<a href="./../../spec/decisions/0008-forms-preserve-service-shape.html">decision 0008</a>).</p><h2 id="why-a-family-not-an-integration" tabindex="-1">Why a family, not an integration <a class="header-anchor" href="#why-a-family-not-an-integration" aria-label="Permalink to &quot;Why a family, not an integration&quot;">​</a></h2><p>A category with a de-facto standard API is never respecified as a Form; Takoform reaches it through a sealed standard-service slot instead (<a href="./../../spec/standard-services/">spec/standard-services</a>). The vector index has no such standard: every major cloud and several independents offer one, each speaking only its own API, which is exactly the category decision 0043 assigns to a Form Family — the place where a host-neutral contract is the only portability there is. Search engines with the Elasticsearch-compatible API sit on the integrate side of that decision&#39;s survey and are not this family. This family replaces the withdrawn v1alpha2 <code>VectorIndex</code>.</p><h2 id="authoring-policy-shape-preserving-contracts" tabindex="-1">Authoring policy: shape-preserving contracts <a class="header-anchor" href="#authoring-policy-shape-preserving-contracts" aria-label="Permalink to &quot;Authoring policy: shape-preserving contracts&quot;">​</a></h2><p>Every member Form preserves one service shape end to end: client API, data model, consistency, update and delete units, error semantics, and the capabilities exposed through typed Bindings. No free semantic token is admitted; a difference in semantics is a different Form, never a selector value. Outward capability use is a digest-bound Binding held by a revision resource; inward activation is an attachment resource (<a href="./../../spec/decisions/0010-exact-interface-and-binding-contracts.html">decision 0010</a>). Desired schemas carry no <code>name</code> or envelope plumbing: the resource envelope owns identity and status (<a href="./../../spec/decisions/0011-resource-identity-generation-and-revision.html">decision 0011</a>).</p><p>This prose accompanies the generated Experimental <code>VectorIndex</code> candidate under <code>forms/candidates/vector.forms.takoform.com</code> and its exact <code>vector.index</code> Interface. The generated candidate bytes, not this proposal, own the current identity. Family membership grants no maturity.</p><h2 id="current-members" tabindex="-1">Current members <a class="header-anchor" href="#current-members" aria-label="Permalink to &quot;Current members&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Form</th><th>Role</th><th>One-line semantics</th><th>Separate-Form boundary</th></tr></thead><tbody><tr><td><a href="./vector-index.html">VectorIndex</a></td><td>identity</td><td>Fixed-dimension dense vector index: metric fixed at creation, namespaced upsert/fetch/query/delete by id, closed metadata filter, approximate top-k similarity.</td><td>A sparse or hybrid keyword index, an exact-kNN guarantee, or a free filter language is a different Form.</td></tr></tbody></table><p>The family deliberately holds ONE Form. <code>dimension</code> and <code>metric</code> are the identity&#39;s only desired fields because changing either means re-embedding the corpus — they are the identity, not configuration — and namespaces are runtime data reached through the Interface, never Resources. Hybrid search or a metadata-schema surface would be separate proposals when that work starts, per <a href="./../../spec/form-families.html">spec/form-families.md</a>.</p>',10)])])}const f=a(o,[["render",s]]);export{m as __pageData,f as default};
